import { useRef } from 'react';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { useGSAP } from '@gsap/react';

gsap.registerPlugin(ScrollTrigger);

export const generateDataWall = (count = 120) => {
  const nodeTypes = ['FUNCTION', 'STRUCT', 'IMPL', 'CONST', 'TRAIT', 'ENUM', 'MATCH', 'INTERFACE', 'CLASS'];
  const actions = ['MODIFIED', 'CREATED', 'DELETED', 'REFACTORED'];
  const rows = [];

  for (let i = 0; i < count; i++) {
    let row = '';
    for (let j = 0; j < 6; j++) {
      const hash = Math.random().toString(16).substring(2, 14) + Math.random().toString(16).substring(2, 14);
      const type = nodeTypes[Math.floor(Math.random() * nodeTypes.length)];
      const action = actions[Math.floor(Math.random() * actions.length)];
      const timestamp = Date.now() - Math.floor(Math.random() * 10000000000);

      row += `[${type}::${action}] ${hash} ${timestamp} | `;
    }
    rows.push(row);
  }
  return rows;
};

export default function WarpedDataWall({ rows }: { rows: string[] }) {
  const cylinderRef = useRef<HTMLDivElement>(null);

  useGSAP(() => {
    gsap.to(cylinderRef.current, {
      rotateX: -80,
      rotateY: 20,
      rotateZ: 45,
      y: -150,
      z: -400,
      ease: "power1.inOut",
      scrollTrigger: {
        trigger: document.body,
        start: "top top",
        end: "bottom bottom",
        scrub: 1,
      }
    });
  });

  return (
    <div className="absolute inset-0 flex items-center justify-center overflow-hidden" style={{ perspective: '1000px' }}>
      <div 
        className="w-full h-full flex items-center justify-center absolute left-[15%] md:left-[25%]"
        style={{ transformStyle: 'preserve-3d', transform: 'rotateY(-15deg) rotateX(10deg)' }}
      >
        <div ref={cylinderRef} className="relative w-full h-full flex items-center justify-center" style={{ transformStyle: 'preserve-3d' }}>
          {rows.map((row, i) => {
            const angle = (i - rows.length / 2) * 2.5; 
            const opacity = 0.15 + (Math.random() * 0.4);

            return (
              <div 
                key={i} 
                className="absolute whitespace-nowrap font-mono text-[11px] md:text-[12px] leading-[1.8] text-[#555] md:text-[#777]"
                style={{
                  opacity,
                  left: '50%',
                  top: '50%',
                  transform: `translate(-50%, -50%) rotateX(${angle}deg) translateZ(700px)`,
                  backfaceVisibility: 'hidden',
                }}
              >
                {row}
              </div>
            );
          })}
        </div>
      </div>

      <div className="absolute inset-0 pointer-events-none bg-gradient-to-r from-[#050505] via-transparent to-[#050505]/30" />
      <div className="absolute inset-0 pointer-events-none bg-gradient-to-b from-[#050505]/80 via-transparent to-[#050505]" />
      <div className="absolute inset-0 pointer-events-none bg-gradient-to-t from-[#050505] via-transparent to-transparent" />
    </div>
  );
}
